const html = "\u003c!doctype html\u003e\n\u003chtml lang=\"vi\"\u003e\n\u003chead\u003e\n  \u003cmeta charset=\"utf-8\"\u003e\n  \u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1\"\u003e\n  \u003cmeta name=\"theme-color\" content=\"#f4f4f1\"\u003e\n  \u003cmeta name=\"color-scheme\" content=\"light\"\u003e\n  \u003ctitle\u003eNguyễn Mạnh Hưng — Environmental Engineer \u0026amp; PMO Manager\u003c/title\u003e\n  \u003cmeta name=\"description\" content=\"Portfolio của Nguyễn Mạnh Hưng — Kỹ sư môi trường và PMO Manager, vận hành hệ thống xử lý nước thải, quản lý O\u0026amp;M và giám sát dự án.\"\u003e\n  \u003cmeta property=\"og:title\" content=\"Nguyễn Mạnh Hưng — Environmental Engineer \u0026amp; PMO Manager\"\u003e\n  \u003cmeta property=\"og:description\" content=\"Vận hành hệ thống xử lý nước thải, quản lý gói thầu O\u0026amp;M và giám sát thi công.\"\u003e\n  \u003cmeta property=\"og:type\" content=\"website\"\u003e\n  \u003cmeta name=\"twitter:card\" content=\"summary_large_image\"\u003e\n  \u003clink rel=\"preconnect\" href=\"https://fonts.googleapis.com\"\u003e\n  \u003clink rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin\u003e\n  \u003clink href=\"https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800\u0026amp;display=swap\" rel=\"stylesheet\"\u003e\n  \u003cstyle\u003e\n    :root {\n      --paper: #f4f4f1;\n      --paper-bright: #ffffff;\n      --ink: #111111;\n      --ink-soft: #464646;\n      --ink-faint: #737373;\n      --blue: #111111;\n      --blue-deep: #111111;\n      --blue-pale: #ececea;\n      --line: rgba(0, 0, 0, 0.12);\n      --line-active: rgba(0, 0, 0, 0.34);\n      --glass: rgba(255, 255, 255, 0.54);\n      --glass-solid: rgba(255, 255, 255, 0.82);\n      --shadow: 0 20px 60px rgba(0, 0, 0, 0.08);\n      --shadow-lifted: 0 28px 70px rgba(0, 0, 0, 0.14);\n      --radius-sm: 18px;\n      --radius-md: 28px;\n      --radius-lg: 40px;\n      --font: \"Manrope\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n      --ease: cubic-bezier(0.22, 1, 0.36, 1);\n    }\n\n    *,\n    *::before,\n    *::after {\n      box-sizing: border-box;\n    }\n\n    html {\n      scroll-behavior: smooth;\n      scroll-padding-top: 7rem;\n    }\n\n    body {\n      min-width: 320px;\n      margin: 0;\n      overflow-x: hidden;\n      background: var(--paper-bright);\n      color: var(--ink);\n      font-family: var(--font);\n      font-size: 1rem;\n      line-height: 1.65;\n      text-rendering: optimizeLegibility;\n      -webkit-font-smoothing: antialiased;\n    }\n\n    body::before {\n      position: fixed;\n      z-index: -2;\n      inset: 0;\n      background-image:\n        linear-gradient(rgba(0, 0, 0, 0.035) 1px, transparent 1px),\n        linear-gradient(90deg, rgba(0, 0, 0, 0.035) 1px, transparent 1px);\n      background-size: 80px 80px;\n      mask-image: linear-gradient(to bottom, black, transparent 64%);\n      content: \"\";\n      pointer-events: none;\n    }\n\n    a {\n      color: inherit;\n      text-decoration: none;\n    }\n\n    button,\n    a {\n      -webkit-tap-highlight-color: transparent;\n    }\n\n    button {\n      color: inherit;\n      font: inherit;\n    }\n\n    :focus-visible {\n      outline: 3px solid rgba(0, 0, 0, 0.52);\n      outline-offset: 4px;\n    }\n\n    ::selection {\n      background: #d8d8d5;\n      color: var(--ink);\n    }\n\n    .skip-link {\n      position: fixed;\n      z-index: 200;\n      top: 0.8rem;\n      left: 0.8rem;\n      padding: 0.75rem 1rem;\n      border-radius: 999px;\n      background: var(--ink);\n      color: #fff;\n      font-size: 0.78rem;\n      font-weight: 700;\n      transform: translateY(-150%);\n      transition: transform 180ms ease;\n    }\n\n    .skip-link:focus {\n      transform: translateY(0);\n    }\n\n    .container {\n      width: min(1180px, calc(100% - 48px));\n      margin-inline: auto;\n    }\n\n    .liquid-glass {\n      --mx: 50%;\n      --my: 0%;\n      position: relative;\n      border: 1px solid var(--line);\n      background:\n        radial-gradient(circle at var(--mx) var(--my), rgba(255, 255, 255, 0.92), transparent 28%),\n        linear-gradient(145deg, rgba(255, 255, 255, 0.76), rgba(239, 239, 236, 0.44)),\n        var(--glass);\n      box-shadow:\n        inset 0 1px 0 rgba(255, 255, 255, 0.9),\n        inset 0 -1px 0 rgba(0, 0, 0, 0.08),\n        var(--shadow);\n      backdrop-filter: blur(24px) saturate(135%);\n      -webkit-backdrop-filter: blur(24px) saturate(135%);\n    }\n\n    .liquid-glass::before {\n      position: absolute;\n      z-index: 0;\n      inset: 0;\n      border-radius: inherit;\n      background:\n        linear-gradient(112deg, transparent 22%, rgba(255, 255, 255, 0.58) 39%, transparent 55%);\n      content: \"\";\n      opacity: 0;\n      pointer-events: none;\n      transform: translateX(-42%);\n      transition:\n        opacity 420ms ease,\n        transform 700ms var(--ease);\n    }\n\n    .liquid-glass:hover::before,\n    .liquid-glass:focus-within::before,\n    .liquid-glass.is-active::before {\n      opacity: 0.72;\n      transform: translateX(35%);\n    }\n\n    .liquid-glass \u003e * {\n      position: relative;\n      z-index: 1;\n    }\n\n    .tilt-card {\n      backface-visibility: hidden;\n      isolation: isolate;\n      transform-origin: center center;\n      transform-style: preserve-3d;\n      will-change: transform, box-shadow;\n      transition:\n        border-color 280ms ease,\n        background-color 280ms ease,\n        box-shadow 420ms var(--ease);\n    }\n\n    .tilt-card.is-active {\n      border-color: rgba(0, 0, 0, 0.38);\n      box-shadow:\n        0 78px 120px rgba(0, 0, 0, 0.22),\n        0 22px 42px rgba(0, 0, 0, 0.14),\n        inset 0 1px 0 rgba(255, 255, 255, 1);\n    }\n\n    .tilt-card \u003e * {\n      backface-visibility: hidden;\n      will-change: transform;\n    }\n\n    body.is-preloading {\n      height: 100svh;\n      overflow: hidden;\n    }\n\n    .site-preloader {\n      display: grid;\n      position: fixed;\n      z-index: 1000;\n      inset: 0;\n      overflow: hidden;\n      background: #d8d8d5;\n      place-items: center;\n      transform: translate3d(0, 0, 0);\n      transition: transform 1.25s cubic-bezier(0.76, 0, 0.24, 1);\n      will-change: transform;\n    }\n\n    .site-preloader.is-exiting {\n      transform: translate3d(0, -105%, 0);\n    }\n\n    .preloader-visual {\n      position: absolute;\n      inset: 0;\n      width: 100%;\n      height: 100%;\n      object-fit: cover;\n    }\n\n    .preloader-message {\n      position: absolute;\n      z-index: 2;\n      bottom: clamp(2rem, 7vh, 5rem);\n      left: 50%;\n      max-width: calc(100% - 2rem);\n      padding: 1rem 1.4rem;\n      border-color: rgba(255, 255, 255, 0.56);\n      border-radius: 999px;\n      background:\n        linear-gradient(145deg, rgba(255, 255, 255, 0.24), rgba(255, 255, 255, 0.08));\n      box-shadow:\n        inset 0 1px 0 rgba(255, 255, 255, 0.72),\n        0 20px 55px rgba(0, 0, 0, 0.16);\n      color: #111111;\n      font-size: clamp(0.95rem, 1.6vw, 1.2rem);\n      font-weight: 800;\n      letter-spacing: -0.025em;\n      text-align: center;\n      white-space: nowrap;\n      opacity: 0;\n      backdrop-filter: blur(28px) saturate(120%);\n      -webkit-backdrop-filter: blur(28px) saturate(120%);\n      transform: translate(-50%, 18px) scale(0.96);\n      transition:\n        opacity 600ms ease,\n        transform 700ms var(--ease);\n    }\n\n    .site-preloader.is-holding .preloader-message {\n      opacity: 1;\n      transform: translate(-50%, 0) scale(1);\n    }\n\n    .site-header {\n      position: fixed;\n      z-index: 100;\n      top: 1rem;\n      left: 0;\n      width: 100%;\n      padding-inline: 1rem;\n      pointer-events: none;\n    }\n\n    .nav-glass {\n      display: grid;\n      grid-template-columns: auto 1fr auto;\n      gap: 0.45rem;\n      align-items: center;\n      width: min(920px, calc(100vw - 32px));\n      min-height: 4.25rem;\n      margin-inline: auto;\n      padding: 0.55rem 0.6rem;\n      border-radius: 999px;\n      pointer-events: auto;\n      transform-origin: top center;\n      transition:\n        box-shadow 500ms ease,\n        background-color 500ms ease;\n    }\n\n    .nav-glass.is-scrolled {\n      width: min(920px, calc(100vw - 32px));\n    }\n\n    .brand {\n      display: inline-flex;\n      align-items: center;\n      justify-self: start;\n      border-radius: 50%;\n    }\n\n    .nav-avatar {\n      display: block;\n      width: 3rem;\n      height: 3rem;\n      border: 1px solid rgba(0, 0, 0, 0.16);\n      border-radius: 50%;\n      background: rgba(238, 238, 235, 0.78);\n      object-fit: cover;\n    }\n\n    .nav-links {\n      display: flex;\n      align-items: center;\n      justify-content: flex-start;\n      justify-self: start;\n      gap: 0.3rem;\n      padding: 0.28rem;\n      border: 1px solid rgba(0, 0, 0, 0.08);\n      border-radius: 999px;\n      background: rgba(255, 255, 255, 0.25);\n    }\n\n    .nav-links \u003e a:not(.nav-cta) {\n      padding: 0.65rem 0.9rem;\n      border-radius: 999px;\n      color: var(--ink-soft);\n      font-size: 0.71rem;\n      font-weight: 600;\n      transition:\n        color 220ms ease,\n        background-color 220ms ease,\n        transform 220ms var(--ease);\n    }\n\n    .nav-links \u003e a:not(.nav-cta):hover,\n    .nav-links \u003e a:not(.nav-cta):focus-visible {\n      background: rgba(255, 255, 255, 0.64);\n      color: var(--blue-deep);\n      transform: translateY(-1px);\n    }\n\n    .nav-cta,\n    .contact-button {\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      border: 1px solid rgba(0, 0, 0, 0.22);\n      border-radius: 999px;\n      background:\n        linear-gradient(145deg, rgba(255, 255, 255, 0.7), rgba(225, 225, 222, 0.62)),\n        #ececea;\n      color: #111111;\n      font-weight: 700;\n      box-shadow:\n        inset 0 1px 0 rgba(255, 255, 255, 0.9),\n        0 8px 20px rgba(0, 0, 0, 0.11);\n    }\n\n    .nav-cta {\n      justify-self: end;\n      min-height: 3rem;\n      padding-inline: 1.15rem;\n      font-size: 0.72rem;\n    }\n\n    .menu-button {\n      display: none;\n      justify-self: end;\n      width: 3rem;\n      height: 3rem;\n      padding: 0;\n      border: 1px solid var(--line);\n      border-radius: 50%;\n      background: rgba(242, 242, 239, 0.78);\n      cursor: pointer;\n    }\n\n    .menu-button span,\n    .menu-button::before {\n      display: block;\n      width: 1rem;\n      height: 1px;\n      margin-inline: auto;\n      background: currentColor;\n      content: \"\";\n      transition: transform 260ms var(--ease);\n    }\n\n    .menu-button span {\n      margin-top: 0.34rem;\n    }\n\n    .menu-button[aria-expanded=\"true\"]::before {\n      transform: translateY(3px) rotate(45deg);\n    }\n\n    .menu-button[aria-expanded=\"true\"] span {\n      transform: translateY(-3px) rotate(-45deg);\n    }\n\n    main {\n      overflow: clip;\n    }\n\n    .hero {\n      display: grid;\n      position: relative;\n      min-height: 100svh;\n      padding-top: 9rem;\n      padding-bottom: 3.5rem;\n      align-items: center;\n      isolation: isolate;\n    }\n\n    .liquid-canvas {\n      position: absolute;\n      z-index: -1;\n      inset: 3rem -10vw 0 35%;\n      width: 75vw;\n      height: calc(100% - 3rem);\n      opacity: 0.92;\n      pointer-events: none;\n    }\n\n    .hero-grid {\n      display: grid;\n      grid-template-columns: minmax(0, 1.45fr) minmax(280px, 0.55fr);\n      gap: clamp(3rem, 8vw, 8rem);\n      align-items: end;\n      perspective: 950px;\n      perspective-origin: 50% 45%;\n    }\n\n    .hero h1 {\n      max-width: 900px;\n      margin: 1.5rem 0 1.75rem;\n      font-size: clamp(2.31rem, 4.785vw, 4.62rem);\n      font-weight: 800;\n      letter-spacing: -0.06em;\n      line-height: 0.9;\n    }\n\n    .hero h1 .accent {\n      color: var(--blue-deep);\n      font-weight: 800;\n    }\n\n    .hero-line {\n      display: block;\n      transform-origin: left center;\n    }\n\n    .hero-intro {\n      max-width: 650px;\n      margin: 0;\n      color: var(--ink-soft);\n      font-size: clamp(1rem, 1.4vw, 1.12rem);\n      line-height: 1.75;\n    }\n\n    .focus-card {\n      min-height: 20rem;\n      padding: 1.6rem;\n      overflow: hidden;\n      border-radius: var(--radius-lg);\n      transform-style: preserve-3d;\n    }\n\n    .focus-card::after {\n      position: absolute;\n      z-index: 0;\n      right: -4rem;\n      bottom: -4rem;\n      width: 12rem;\n      height: 12rem;\n      border: 1px solid rgba(0, 0, 0, 0.14);\n      border-radius: 50%;\n      background: rgba(225, 225, 222, 0.3);\n      content: \"\";\n      box-shadow:\n        0 0 0 2rem rgba(0, 0, 0, 0.035),\n        0 0 0 4rem rgba(0, 0, 0, 0.02);\n    }\n\n    .focus-card-inner {\n      display: flex;\n      min-height: 16.8rem;\n      flex-direction: column;\n      justify-content: space-between;\n      transform: translateZ(28px);\n    }\n\n    .focus-list {\n      display: grid;\n      gap: 0.55rem;\n      margin: 2rem 0;\n      font-size: 1.32rem;\n      font-weight: 600;\n      letter-spacing: -0.04em;\n      line-height: 1.12;\n    }\n\n    .location {\n      display: flex;\n      align-items: center;\n      gap: 0.55rem;\n      color: var(--ink-faint);\n      font-size: 0.72rem;\n    }\n\n    .location::before {\n      width: 0.48rem;\n      height: 0.48rem;\n      border: 1px solid var(--blue);\n      border-radius: 50%;\n      background: rgba(218, 218, 215, 0.82);\n      box-shadow: 0 0 0 4px rgba(0, 0, 0, 0.06);\n      content: \"\";\n    }\n\n    .section {\n      position: relative;\n      padding-block: clamp(6rem, 11vw, 10rem);\n    }\n\n    .section-rule {\n      border-top: 1px solid var(--line);\n    }\n\n    .section-header {\n      margin-bottom: clamp(3.5rem, 7vw, 6.5rem);\n    }\n\n    .section-header h2 {\n      max-width: 760px;\n      margin: 0;\n      font-size: clamp(1.65rem, 3.41vw, 3.3rem);\n      font-weight: 800;\n      letter-spacing: -0.05em;\n      line-height: 0.95;\n    }\n\n    .statement-grid {\n      display: grid;\n      grid-template-columns: minmax(0, 1.55fr) minmax(250px, 0.45fr);\n      gap: clamp(3rem, 9vw, 8rem);\n      align-items: start;\n    }\n\n    .statement-main {\n      max-width: 820px;\n      margin: 0;\n      font-size: clamp(1.6rem, 2.8vw, 2.8rem);\n      font-weight: 700;\n      letter-spacing: -0.04em;\n      line-height: 1.08;\n    }\n\n    .statement-support {\n      margin: 0;\n      padding-top: 0.5rem;\n      color: var(--ink-soft);\n      font-size: 0.92rem;\n      line-height: 1.9;\n    }\n\n    .metrics-grid {\n      display: grid;\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n      gap: 1rem;\n      margin-top: clamp(4.5rem, 8vw, 8rem);\n      perspective: 950px;\n      perspective-origin: 50% 42%;\n    }\n\n    .metric-card,\n    .capability-card {\n      overflow: hidden;\n      transform-style: preserve-3d;\n      will-change: transform;\n    }\n\n    .metric-card {\n      min-height: 14rem;\n      padding: 1.6rem;\n      border-radius: var(--radius-md);\n    }\n\n    .metric-value {\n      display: block;\n      color: var(--blue-deep);\n      font-size: clamp(4.7rem, 8vw, 7rem);\n      font-weight: 500;\n      letter-spacing: -0.075em;\n      line-height: 0.85;\n      transform: translateZ(34px);\n    }\n\n    .metric-label {\n      display: block;\n      position: absolute;\n      right: 1.6rem;\n      bottom: 1.45rem;\n      left: 1.6rem;\n      color: var(--ink-soft);\n      font-size: 0.75rem;\n      line-height: 1.55;\n      transform: translateZ(22px);\n    }\n\n    .capabilities-section {\n      padding-top: 1.5rem;\n    }\n\n    .capability-grid {\n      display: grid;\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n      gap: 1rem;\n      perspective: 950px;\n      perspective-origin: 50% 42%;\n    }\n\n    .capability-card {\n      display: flex;\n      min-height: 18rem;\n      padding: 1.7rem;\n      border-radius: var(--radius-md);\n      flex-direction: column;\n      justify-content: flex-end;\n    }\n\n    .capability-copy {\n      transform: translateZ(30px);\n    }\n\n    .capability-copy h3 {\n      max-width: 14ch;\n      margin: 0 0 1.2rem;\n      font-size: clamp(0.99rem, 1.705vw, 1.54rem);\n      font-weight: 800;\n      letter-spacing: -0.045em;\n      line-height: 1.02;\n    }\n\n    .capability-copy p {\n      max-width: 37ch;\n      margin: 0;\n      color: var(--ink-soft);\n      font-size: 0.8rem;\n      line-height: 1.75;\n    }\n\n    .projects-section {\n      padding-top: clamp(6rem, 11vw, 10rem);\n    }\n\n    .project-list {\n      border-top: 1px solid var(--line);\n    }\n\n    .project-row {\n      display: grid;\n      grid-template-columns: minmax(0, 1fr) minmax(8rem, 0.38fr) 3rem;\n      gap: 1.5rem;\n      align-items: center;\n      min-height: 9rem;\n      padding: 1.35rem 1rem;\n      border-bottom: 1px solid var(--line);\n      border-radius: var(--radius-sm);\n      transition:\n        background-color 350ms ease,\n        box-shadow 350ms ease,\n        border-color 350ms ease;\n    }\n\n    .project-row:hover,\n    .project-row:focus-within {\n      border-color: rgba(0, 0, 0, 0.18);\n      background: rgba(255, 255, 255, 0.52);\n      box-shadow:\n        inset 0 1px 0 rgba(255, 255, 255, 0.9),\n        0 16px 40px rgba(0, 0, 0, 0.07);\n      backdrop-filter: blur(18px);\n      -webkit-backdrop-filter: blur(18px);\n    }\n\n    .project-title {\n      max-width: 24ch;\n      font-size: clamp(0.99rem, 1.925vw, 1.7875rem);\n      font-weight: 800;\n      letter-spacing: -0.04em;\n      line-height: 1.02;\n    }\n\n    .project-role {\n      color: var(--ink-faint);\n      font-size: 0.74rem;\n      line-height: 1.55;\n    }\n\n    .project-arrow {\n      display: inline-grid;\n      width: 2.7rem;\n      height: 2.7rem;\n      border: 1px solid rgba(0, 0, 0, 0.14);\n      border-radius: 50%;\n      background: rgba(238, 238, 235, 0.62);\n      color: var(--blue-deep);\n      font-size: 1.15rem;\n      place-items: center;\n    }\n\n    .contact-section {\n      padding-top: 4rem;\n      padding-bottom: 1.5rem;\n    }\n\n    .contact-section .container {\n      perspective: 1100px;\n      perspective-origin: 50% 40%;\n    }\n\n    .contact-panel {\n      position: relative;\n      min-height: 34rem;\n      padding: clamp(2.2rem, 7vw, 6rem);\n      overflow: hidden;\n      border-radius: var(--radius-lg);\n      transform-style: preserve-3d;\n    }\n\n    .contact-panel::after {\n      position: absolute;\n      z-index: 0;\n      right: -9rem;\n      bottom: -11rem;\n      width: 32rem;\n      height: 32rem;\n      border: 1px solid rgba(0, 0, 0, 0.14);\n      border-radius: 42% 58% 60% 40% / 45% 40% 60% 55%;\n      background:\n        radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.72), transparent 34%),\n        rgba(220, 220, 217, 0.38);\n      box-shadow:\n        0 0 0 3rem rgba(0, 0, 0, 0.035),\n        0 0 0 7rem rgba(0, 0, 0, 0.02);\n      content: \"\";\n      filter: blur(1px);\n      transform: rotate(-12deg);\n    }\n\n    .contact-content {\n      display: flex;\n      min-height: 22rem;\n      flex-direction: column;\n      justify-content: center;\n      transform: translateZ(28px);\n    }\n\n    .contact-panel h2 {\n      max-width: 900px;\n      margin: 1.2rem 0 1.6rem;\n      font-size: clamp(1.925rem, 3.96vw, 3.85rem);\n      font-weight: 800;\n      letter-spacing: -0.055em;\n      line-height: 0.92;\n    }\n\n    .contact-panel p {\n      max-width: 560px;\n      margin: 0 0 2rem;\n      color: var(--ink-soft);\n      font-size: 0.92rem;\n    }\n\n    .contact-button {\n      width: max-content;\n      min-height: 3.5rem;\n      padding: 0.85rem 1rem 0.85rem 1.3rem;\n      gap: 2rem;\n      font-size: 0.78rem;\n      transform-origin: center;\n    }\n\n    .contact-button span {\n      display: inline-grid;\n      width: 2rem;\n      height: 2rem;\n      border-radius: 50%;\n      background: rgba(255, 255, 255, 0.5);\n      font-size: 1rem;\n      font-weight: 400;\n      place-items: center;\n    }\n\n    .site-footer {\n      position: relative;\n      z-index: 0;\n      padding-block: 1.5rem 2.5rem;\n    }\n\n    .footer-glass {\n      display: grid;\n      grid-template-columns: 1fr auto;\n      gap: 1.5rem;\n      align-items: center;\n      min-height: 4.5rem;\n      padding: 0.7rem 0.8rem 0.7rem 1.3rem;\n      border-radius: 999px;\n      color: var(--ink-faint);\n      font-size: 0.61rem;\n      font-weight: 700;\n      letter-spacing: 0.07em;\n      text-transform: uppercase;\n    }\n\n    .back-to-top {\n      display: inline-flex;\n      align-items: center;\n      justify-self: end;\n      gap: 0.65rem;\n      min-height: 3rem;\n      padding-inline: 1rem;\n      border: 1px solid rgba(0, 0, 0, 0.12);\n      border-radius: 999px;\n      background: rgba(239, 239, 236, 0.62);\n      color: var(--blue-deep);\n    }\n\n    .back-to-top b {\n      font-size: 0.9rem;\n      font-weight: 500;\n    }\n\n    @media (max-width: 940px) {\n      .hero-grid {\n        grid-template-columns: minmax(0, 1.35fr) minmax(250px, 0.55fr);\n        gap: 2.5rem;\n      }\n\n      .hero h1 {\n        font-size: clamp(2.2rem, 5.775vw, 3.74rem);\n      }\n\n      .statement-grid {\n        grid-template-columns: minmax(0, 1.25fr) minmax(220px, 0.5fr);\n        gap: 3rem;\n      }\n\n      .capability-card {\n        min-height: 24rem;\n      }\n\n      .project-row {\n        grid-template-columns: minmax(0, 1fr) 7.5rem 2.8rem;\n      }\n    }\n\n    @media (max-width: 720px) {\n      html {\n        scroll-padding-top: 5.75rem;\n      }\n\n      .container {\n        width: min(100% - 30px, 1180px);\n      }\n\n      .site-header {\n        top: 0.65rem;\n        padding-inline: 0.65rem;\n      }\n\n      .nav-glass,\n      .nav-glass.is-scrolled {\n        grid-template-columns: 1fr auto;\n        width: 100%;\n        min-height: 3.75rem;\n        padding: 0.38rem;\n      }\n\n      .menu-button {\n        display: block;\n      }\n\n      .nav-cta {\n        display: none;\n      }\n\n      .nav-links {\n        display: grid;\n        position: absolute;\n        top: calc(100% + 0.55rem);\n        right: 0;\n        left: 0;\n        gap: 0;\n        padding: 0.6rem;\n        border: 1px solid var(--line);\n        border-radius: 1.5rem;\n        background:\n          linear-gradient(145deg, rgba(255, 255, 255, 0.88), rgba(235, 235, 232, 0.76));\n        box-shadow: var(--shadow);\n        backdrop-filter: blur(24px) saturate(135%);\n        -webkit-backdrop-filter: blur(24px) saturate(135%);\n        opacity: 0;\n        pointer-events: none;\n        transform: translateY(-0.65rem);\n        visibility: hidden;\n      }\n\n      .nav-links[data-open=\"true\"] {\n        opacity: 1;\n        pointer-events: auto;\n        transform: translateY(0);\n        visibility: visible;\n      }\n\n      .nav-links \u003e a:not(.nav-cta) {\n        padding: 0.9rem 1rem;\n        border-radius: 0.9rem;\n      }\n\n      .nav-links \u003e a + a:not(.nav-cta) {\n        border-top: 1px solid rgba(0, 0, 0, 0.08);\n      }\n\n      .hero {\n        min-height: auto;\n        padding-top: 8rem;\n        padding-bottom: 4rem;\n      }\n\n      .liquid-canvas {\n        inset: 5rem -40vw auto 20%;\n        width: 120vw;\n        height: 36rem;\n        opacity: 0.7;\n      }\n\n      .hero-grid,\n      .statement-grid {\n        grid-template-columns: 1fr;\n      }\n\n      .hero-grid {\n        gap: 3rem;\n      }\n\n      .hero h1 {\n        font-size: clamp(2.035rem, 9.79vw, 3.19rem);\n      }\n\n      .focus-card {\n        min-height: 16rem;\n      }\n\n      .focus-card-inner {\n        min-height: 12.8rem;\n      }\n\n      .metrics-grid,\n      .capability-grid {\n        grid-template-columns: 1fr;\n      }\n\n      .metric-card {\n        min-height: 11.5rem;\n      }\n\n      .capability-card {\n        min-height: 21rem;\n      }\n\n      .project-row {\n        grid-template-columns: minmax(0, 1fr) 2.7rem;\n        gap: 0.75rem;\n        min-height: 8rem;\n        padding-inline: 0.4rem;\n      }\n\n      .project-role {\n        display: none;\n      }\n\n      .project-title {\n        font-size: clamp(0.9075rem, 4.29vw, 1.32rem);\n      }\n\n      .contact-panel {\n        min-height: 31rem;\n        padding-block: 3.5rem;\n      }\n\n      .footer-glass {\n        grid-template-columns: 1fr auto;\n      }\n    }\n\n    @media (max-width: 390px) {\n      .hero h1 {\n        font-size: 1.925rem;\n      }\n\n      .contact-panel h2 {\n        font-size: 1.7325rem;\n      }\n    }\n\n    @media (hover: none) {\n      .metric-card,\n      .capability-card,\n      .focus-card,\n      .contact-panel {\n        will-change: auto;\n      }\n    }\n\n    @media (prefers-contrast: more) {\n      :root {\n        --line: rgba(0, 0, 0, 0.46);\n      }\n\n      .liquid-glass,\n      .nav-links {\n        background: rgba(255, 255, 255, 0.94);\n        backdrop-filter: none;\n        -webkit-backdrop-filter: none;\n      }\n    }\n\n    @media (prefers-reduced-motion: reduce) {\n      html {\n        scroll-behavior: auto;\n      }\n\n      *,\n      *::before,\n      *::after {\n        animation-duration: 0.01ms !important;\n        animation-iteration-count: 1 !important;\n        scroll-behavior: auto !important;\n        transition-duration: 0.01ms !important;\n      }\n\n      .liquid-canvas {\n        opacity: 0.46;\n      }\n    }\n\n    @supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {\n      .liquid-glass,\n      .nav-links {\n        background: rgba(255, 255, 255, 0.96);\n      }\n    }\n  \u003c/style\u003e\n\u003c/head\u003e\n\u003cbody\u003e\n  \u003cdiv class=\"site-preloader\" id=\"site-preloader\" role=\"status\" aria-live=\"polite\" aria-label=\"Đang tải hồ sơ\"\u003e\n    \u003cimg class=\"preloader-visual\" id=\"preloader-visual\" src=\"assets/preload-first.webp\" alt=\"\"\u003e\n    \u003cdiv class=\"preloader-message liquid-glass\"\u003eHợp tác vận hành từ hôm nay\u003c/div\u003e\n  \u003c/div\u003e\n\n  \u003ca class=\"skip-link\" href=\"#main-content\"\u003eChuyển đến nội dung chính\u003c/a\u003e\n\n  \u003cheader class=\"site-header\"\u003e\n    \u003cnav class=\"nav-glass liquid-glass\" aria-label=\"Điều hướng chính\"\u003e\n      \u003ca class=\"brand\" href=\"#top\" aria-label=\"Nguyễn Mạnh Hưng — về đầu trang\"\u003e\n        \u003cimg class=\"nav-avatar\" src=\"assets/avatar-nguyen-manh-hung.png\" alt=\"\"\u003e\n      \u003c/a\u003e\n\n      \u003cdiv class=\"nav-links\" id=\"navigation-links\" data-open=\"false\"\u003e\n        \u003ca href=\"#about\"\u003eGiới thiệu\u003c/a\u003e\n        \u003ca href=\"#capabilities\"\u003eNăng lực\u003c/a\u003e\n        \u003ca href=\"#projects\"\u003eDự án\u003c/a\u003e\n      \u003c/div\u003e\n\n      \u003ca class=\"nav-cta magnetic\" href=\"#contact\"\u003eHợp tác\u003c/a\u003e\n\n      \u003cbutton class=\"menu-button\" type=\"button\" aria-expanded=\"false\" aria-controls=\"navigation-links\" aria-label=\"Mở menu\"\u003e\n        \u003cspan aria-hidden=\"true\"\u003e\u003c/span\u003e\n      \u003c/button\u003e\n    \u003c/nav\u003e\n  \u003c/header\u003e\n\n  \u003cmain id=\"main-content\"\u003e\n    \u003csection class=\"hero container\" id=\"top\" aria-labelledby=\"hero-title\"\u003e\n      \u003cdiv class=\"hero-grid\"\u003e\n        \u003cdiv class=\"hero-copy\"\u003e\n          \u003ch1 id=\"hero-title\"\u003e\n            \u003cspan class=\"hero-line\"\u003eVận hành chuẩn.\u003c/span\u003e\n            \u003cspan class=\"hero-line accent\"\u003eNghiệm thu rõ.\u003c/span\u003e\n          \u003c/h1\u003e\n          \u003cp class=\"hero-intro\"\u003eQuản lý vận hành XLNT, gói thầu O\u0026amp;M và giám sát thi công.\u003c/p\u003e\n        \u003c/div\u003e\n\n        \u003caside class=\"focus-card liquid-glass tilt-card\" aria-label=\"Thông tin chuyên môn\"\u003e\n          \u003cdiv class=\"focus-card-inner\"\u003e\n            \u003cdiv class=\"focus-list\"\u003e\n              \u003cspan\u003eVận hành XLNT\u003c/span\u003e\n              \u003cspan\u003eQuản lý O\u0026amp;M\u003c/span\u003e\n              \u003cspan\u003eGiám sát thi công\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cspan class=\"location\"\u003eHạ Long, Quảng Ninh · Việt Nam\u003c/span\u003e\n          \u003c/div\u003e\n        \u003c/aside\u003e\n      \u003c/div\u003e\n    \u003c/section\u003e\n\n    \u003csection class=\"section section-rule\" id=\"about\" aria-labelledby=\"about-title\"\u003e\n      \u003cdiv class=\"container\"\u003e\n        \u003cheader class=\"section-header\" data-reveal\u003e\n          \u003ch2 id=\"about-title\"\u003eKỷ luật vận hành.\u003c/h2\u003e\n        \u003c/header\u003e\n\n        \u003cdiv class=\"statement-grid\"\u003e\n          \u003cp class=\"statement-main\" data-reveal\u003eVận hành ổn định. Chất lượng minh bạch. Tiến độ rõ ràng.\u003c/p\u003e\n          \u003cp class=\"statement-support\" data-reveal\u003eKết nối kỹ thuật, con người và nguồn lực để dự án đúng hướng.\u003c/p\u003e\n        \u003c/div\u003e\n\n        \u003cdiv class=\"metrics-grid\" aria-label=\"Các số liệu chính\"\u003e\n          \u003carticle class=\"metric-card liquid-glass tilt-card\" data-reveal\u003e\n            \u003cstrong class=\"metric-value\" data-count=\"4\" data-suffix=\"+\"\u003e4+\u003c/strong\u003e\n            \u003cspan class=\"metric-label\"\u003eNăm kinh nghiệm\u003c/span\u003e\n          \u003c/article\u003e\n\n          \u003carticle class=\"metric-card liquid-glass tilt-card\" data-reveal\u003e\n            \u003cstrong class=\"metric-value\" data-count=\"8\"\u003e8\u003c/strong\u003e\n            \u003cspan class=\"metric-label\"\u003eNhà máy quản lý O\u0026amp;M\u003c/span\u003e\n          \u003c/article\u003e\n\n          \u003carticle class=\"metric-card liquid-glass tilt-card\" data-reveal\u003e\n            \u003cstrong class=\"metric-value\" data-count=\"17\"\u003e17\u003c/strong\u003e\n            \u003cspan class=\"metric-label\"\u003eDự án môi trường\u003c/span\u003e\n          \u003c/article\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n    \u003c/section\u003e\n\n    \u003csection class=\"section capabilities-section\" id=\"capabilities\" aria-labelledby=\"capabilities-title\"\u003e\n      \u003cdiv class=\"container\"\u003e\n        \u003cheader class=\"section-header\" data-reveal\u003e\n          \u003ch2 id=\"capabilities-title\"\u003eNăng lực cốt lõi.\u003c/h2\u003e\n        \u003c/header\u003e\n\n        \u003cdiv class=\"capability-grid\"\u003e\n          \u003carticle class=\"capability-card liquid-glass tilt-card\" data-reveal\u003e\n            \u003cdiv class=\"capability-copy\"\u003e\n              \u003ch3\u003eVận hành XLNT\u003c/h3\u003e\n              \u003cp\u003eKiểm soát AAO, MBBR, MBR, SBR, chỉ tiêu, hóa chất và thiết bị.\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/article\u003e\n\n          \u003carticle class=\"capability-card liquid-glass tilt-card\" data-reveal\u003e\n            \u003cdiv class=\"capability-copy\"\u003e\n              \u003ch3\u003eQuản lý O\u0026amp;M\u003c/h3\u003e\n              \u003cp\u003eKiểm soát kế hoạch, chi phí, nhân sự, vật tư, báo cáo và nghiệm thu.\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/article\u003e\n\n          \u003carticle class=\"capability-card liquid-glass tilt-card\" data-reveal\u003e\n            \u003cdiv class=\"capability-copy\"\u003e\n              \u003ch3\u003eGiám sát thi công\u003c/h3\u003e\n              \u003cp\u003eKiểm soát lắp đặt, bản vẽ, hiện trường, tiến độ và an toàn.\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/article\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n    \u003c/section\u003e\n\n    \u003csection class=\"section projects-section\" id=\"projects\" aria-labelledby=\"projects-title\"\u003e\n      \u003cdiv class=\"container\"\u003e\n        \u003cheader class=\"section-header\" data-reveal\u003e\n          \u003ch2 id=\"projects-title\"\u003ePhạm vi triển khai.\u003c/h2\u003e\n        \u003c/header\u003e\n\n        \u003cdiv class=\"project-list\" aria-label=\"Các nhóm dự án\"\u003e\n          \u003carticle class=\"project-row\" data-reveal\u003e\n            \u003cspan class=\"project-title\"\u003eHệ thống xử lý nước thải\u003c/span\u003e\n            \u003cspan class=\"project-role\"\u003eVận hành \u0026amp; tối ưu\u003c/span\u003e\n            \u003cspan class=\"project-arrow\" aria-hidden=\"true\"\u003e→\u003c/span\u003e\n          \u003c/article\u003e\n\n          \u003carticle class=\"project-row\" data-reveal\u003e\n            \u003cspan class=\"project-title\"\u003eVận hành \u0026amp; bảo dưỡng O\u0026amp;M\u003c/span\u003e\n            \u003cspan class=\"project-role\"\u003eQuản lý O\u0026amp;M\u003c/span\u003e\n            \u003cspan class=\"project-arrow\" aria-hidden=\"true\"\u003e→\u003c/span\u003e\n          \u003c/article\u003e\n\n          \u003carticle class=\"project-row\" data-reveal\u003e\n            \u003cspan class=\"project-title\"\u003eThi công tại Hà Nội, Hải Phòng \u0026amp; Quảng Ninh\u003c/span\u003e\n            \u003cspan class=\"project-role\"\u003eGiám sát thi công\u003c/span\u003e\n            \u003cspan class=\"project-arrow\" aria-hidden=\"true\"\u003e→\u003c/span\u003e\n          \u003c/article\u003e\n        \u003c/div\u003e\n\n      \u003c/div\u003e\n    \u003c/section\u003e\n\n    \u003csection class=\"section contact-section\" id=\"contact\" aria-labelledby=\"contact-title\"\u003e\n      \u003cdiv class=\"container\"\u003e\n        \u003cdiv class=\"contact-panel liquid-glass tilt-card\" data-reveal\u003e\n          \u003cdiv class=\"contact-content\"\u003e\n            \u003ch2 id=\"contact-title\"\u003eHợp tác vận hành.\u003c/h2\u003e\n            \u003cp\u003eVận hành, cải tạo hoặc giám sát thi công hệ thống XLNT.\u003c/p\u003e\n            \u003ca class=\"contact-button magnetic\" href=\"mailto:thombeohau@gmail.com\"\u003e\n              Liên hệ hợp tác\n              \u003cspan aria-hidden=\"true\"\u003e→\u003c/span\u003e\n            \u003c/a\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n    \u003c/section\u003e\n  \u003c/main\u003e\n\n  \u003cfooter class=\"site-footer container\"\u003e\n    \u003cdiv class=\"footer-glass liquid-glass\"\u003e\n      \u003cspan\u003e© 2025 Nguyễn Mạnh Hưng\u003c/span\u003e\n      \u003ca class=\"back-to-top magnetic\" href=\"#top\"\u003e\n        Về đầu trang\n        \u003cb aria-hidden=\"true\"\u003e↑\u003c/b\u003e\n      \u003c/a\u003e\n    \u003c/div\u003e\n  \u003c/footer\u003e\n\n  \u003cscript\u003e\n    (() =\u003e {\n      const preloader = document.querySelector(\"#site-preloader\");\n      const visual = document.querySelector(\"#preloader-visual\");\n      const reduceMotion = window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n      const sequenceDuration = 7167;\n      const holdDuration = reduceMotion ? 900 : 3000;\n      let sequenceTimer = 0;\n      let holdTimer = 0;\n      let fallbackTimer = 0;\n      let sequenceObjectUrl = \"\";\n      let finished = false;\n\n      if (!preloader || !visual) return;\n      document.body.classList.add(\"is-preloading\");\n\n      const removePreloader = () =\u003e {\n        if (!preloader.isConnected) return;\n        if (sequenceObjectUrl) URL.revokeObjectURL(sequenceObjectUrl);\n        preloader.remove();\n        document.body.classList.remove(\"is-preloading\");\n      };\n\n      const exitPreloader = () =\u003e {\n        if (finished) return;\n        finished = true;\n        clearTimeout(sequenceTimer);\n        clearTimeout(holdTimer);\n        preloader.classList.add(\"is-exiting\");\n        preloader.setAttribute(\"aria-label\", \"Hồ sơ đã sẵn sàng\");\n        preloader.addEventListener(\"transitionend\", removePreloader, { once: true });\n        fallbackTimer = window.setTimeout(removePreloader, reduceMotion ? 100 : 1600);\n      };\n\n      const holdFinalFrame = () =\u003e {\n        clearTimeout(sequenceTimer);\n        visual.src = \"assets/preload-final.webp\";\n        preloader.classList.add(\"is-holding\");\n        preloader.setAttribute(\"aria-label\", \"Hợp tác vận hành từ hôm nay\");\n        holdTimer = window.setTimeout(exitPreloader, holdDuration);\n      };\n\n      const startSequence = async () =\u003e {\n        if (reduceMotion) {\n          visual.addEventListener(\"load\", holdFinalFrame, { once: true });\n          visual.src = \"assets/preload-final.webp\";\n          return;\n        }\n\n        try {\n          const response = await fetch(\"assets/preload-sequence-12fps.webp\", {\n            cache: \"force-cache\"\n          });\n          if (!response.ok) throw new Error(\"Preload animation unavailable\");\n\n          sequenceObjectUrl = URL.createObjectURL(await response.blob());\n          visual.addEventListener(\"load\", () =\u003e {\n            requestAnimationFrame(() =\u003e {\n              sequenceTimer = window.setTimeout(holdFinalFrame, sequenceDuration);\n            });\n          }, { once: true });\n          visual.src = sequenceObjectUrl;\n        } catch {\n          holdFinalFrame();\n        }\n      };\n\n      visual.addEventListener(\"error\", holdFinalFrame, { once: true });\n      startSequence();\n\n      document.addEventListener(\"keydown\", (event) =\u003e {\n        if (event.key === \"Escape\") exitPreloader();\n      }, { once: true });\n\n      window.addEventListener(\"pagehide\", () =\u003e {\n        clearTimeout(sequenceTimer);\n        clearTimeout(holdTimer);\n        clearTimeout(fallbackTimer);\n      }, { once: true });\n    })();\n  \u003c/script\u003e\n\n  \u003cscript src=\"https://cdn.jsdelivr.net/npm/gsap@3.13.0/dist/gsap.min.js\" defer\u003e\u003c/script\u003e\n  \u003cscript src=\"https://cdn.jsdelivr.net/npm/gsap@3.13.0/dist/ScrollTrigger.min.js\" defer\u003e\u003c/script\u003e\n\n  \u003cscript\u003e\n    window.addEventListener(\"load\", () =\u003e {\n      const menuButton = document.querySelector(\".menu-button\");\n      const navigation = document.querySelector(\".nav-links\");\n      const navGlass = document.querySelector(\".nav-glass\");\n      const mobileQuery = window.matchMedia(\"(max-width: 720px)\");\n      const reduceMotion = window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n      const gsapReady = typeof window.gsap !== \"undefined\";\n      const scrollTriggerReady = typeof window.ScrollTrigger !== \"undefined\";\n\n      const closeMenu = (returnFocus = false) =\u003e {\n        if (!menuButton || !navigation) return;\n        menuButton.setAttribute(\"aria-expanded\", \"false\");\n        menuButton.setAttribute(\"aria-label\", \"Mở menu\");\n\n        if (\n          gsapReady \u0026\u0026\n          mobileQuery.matches \u0026\u0026\n          !reduceMotion \u0026\u0026\n          navigation.dataset.open === \"true\"\n        ) {\n          window.gsap.to(navigation, {\n            autoAlpha: 0,\n            y: -10,\n            duration: 0.28,\n            ease: \"power3.inOut\",\n            onComplete: () =\u003e {\n              navigation.dataset.open = \"false\";\n              navigation.style.pointerEvents = \"none\";\n            }\n          });\n        } else {\n          navigation.dataset.open = \"false\";\n        }\n\n        if (returnFocus) menuButton.focus();\n      };\n\n      if (menuButton \u0026\u0026 navigation) {\n        menuButton.addEventListener(\"click\", () =\u003e {\n          const willOpen = menuButton.getAttribute(\"aria-expanded\") !== \"true\";\n          if (!willOpen) {\n            closeMenu();\n            return;\n          }\n\n          menuButton.setAttribute(\"aria-expanded\", \"true\");\n          menuButton.setAttribute(\"aria-label\", \"Đóng menu\");\n          navigation.dataset.open = \"true\";\n\n          if (gsapReady \u0026\u0026 mobileQuery.matches \u0026\u0026 !reduceMotion) {\n            window.gsap.fromTo(navigation, {\n              autoAlpha: 0,\n              y: -10\n            }, {\n              autoAlpha: 1,\n              y: 0,\n              duration: 0.38,\n              ease: \"power3.out\",\n              onStart: () =\u003e {\n                navigation.style.pointerEvents = \"auto\";\n              }\n            });\n          }\n        });\n\n        navigation.addEventListener(\"click\", (event) =\u003e {\n          if (event.target.closest(\"a\")) closeMenu();\n        });\n\n        document.addEventListener(\"keydown\", (event) =\u003e {\n          if (event.key === \"Escape\" \u0026\u0026 menuButton.getAttribute(\"aria-expanded\") === \"true\") {\n            closeMenu(true);\n          }\n        });\n\n        document.addEventListener(\"click\", (event) =\u003e {\n          if (mobileQuery.matches \u0026\u0026 !event.target.closest(\".nav-glass\")) closeMenu();\n        });\n\n        mobileQuery.addEventListener(\"change\", () =\u003e {\n          closeMenu();\n          if (!mobileQuery.matches \u0026\u0026 gsapReady) {\n            window.gsap.set(navigation, { clearProps: \"all\" });\n          }\n        });\n      }\n\n      document.querySelectorAll(\".liquid-glass\").forEach((surface) =\u003e {\n        surface.addEventListener(\"pointermove\", (event) =\u003e {\n          const rect = surface.getBoundingClientRect();\n          surface.style.setProperty(\"--mx\", `${event.clientX - rect.left}px`);\n          surface.style.setProperty(\"--my\", `${event.clientY - rect.top}px`);\n        });\n      });\n\n      if (!gsapReady || !scrollTriggerReady) return;\n\n      const { gsap, ScrollTrigger } = window;\n      gsap.registerPlugin(ScrollTrigger);\n\n      if (navGlass) {\n        ScrollTrigger.create({\n          start: 80,\n          onUpdate: (self) =\u003e {\n            navGlass.classList.toggle(\"is-scrolled\", self.scroll() \u003e 80);\n          }\n        });\n      }\n\n      if (!reduceMotion) {\n        const heroTimeline = gsap.timeline({ defaults: { ease: \"power4.out\" } });\n        heroTimeline\n          .from(\".hero-line\", {\n            yPercent: 105,\n            autoAlpha: 0,\n            rotate: 1.4,\n            duration: 1,\n            stagger: 0.09\n          }, \"-=0.35\")\n          .from(\".hero-intro\", { y: 24, autoAlpha: 0, duration: 0.75 }, \"-=0.6\")\n          .from(\".focus-card\", { y: 38, autoAlpha: 0, scale: 0.96, duration: 0.9 }, \"-=0.7\");\n\n        gsap.utils.toArray(\"[data-reveal]\").forEach((element) =\u003e {\n          gsap.from(element, {\n            y: 42,\n            autoAlpha: 0,\n            duration: 0.9,\n            ease: \"power3.out\",\n            scrollTrigger: {\n              trigger: element,\n              start: \"top 88%\",\n              once: true\n            }\n          });\n        });\n\n        document.querySelectorAll(\"[data-count]\").forEach((counter) =\u003e {\n          const finalValue = Number(counter.dataset.count);\n          const suffix = counter.dataset.suffix || \"\";\n          const state = { value: 0 };\n\n          ScrollTrigger.create({\n            trigger: counter,\n            start: \"top 90%\",\n            once: true,\n            onEnter: () =\u003e {\n              gsap.to(state, {\n                value: finalValue,\n                duration: 1.4,\n                ease: \"power3.out\",\n                onUpdate: () =\u003e {\n                  counter.textContent = `${Math.round(state.value)}${suffix}`;\n                }\n              });\n            }\n          });\n        });\n      }\n\n      const clampTilt = (value, min, max) =\u003e Math.min(Math.max(value, min), max);\n\n      document.querySelectorAll(\".tilt-card\").forEach((card) =\u003e {\n        const isContactPanel = card.classList.contains(\"contact-panel\");\n        const maxTilt = isContactPanel ? 8 : 16;\n        const lift = isContactPanel ? -20 : -36;\n        const depth = isContactPanel ? 42 : 72;\n        const scale = isContactPanel ? 1.02 : 1.055;\n        const layers = Array.from(card.children);\n        const current = { x: 0, y: 0, rx: 0, ry: 0, z: 0, scale: 1 };\n        const target = { x: 0, y: 0, rx: 0, ry: 0, z: 0, scale: 1 };\n        let restingRect = null;\n        let frameId = 0;\n\n        const renderCard = () =\u003e {\n          const isEntering = card.classList.contains(\"is-active\");\n          const ease = reduceMotion ? 0.16 : isEntering ? 0.085 : 0.095;\n\n          Object.keys(current).forEach((property) =\u003e {\n            current[property] += (target[property] - current[property]) * ease;\n          });\n\n          card.style.transform =\n            `perspective(820px) translate3d(${current.x}px, ${current.y}px, ${current.z}px) ` +\n            `rotateX(${current.rx}deg) rotateY(${current.ry}deg) scale(${current.scale})`;\n\n          layers.forEach((layer, index) =\u003e {\n            const layerDepth = 34 + index * 7;\n            layer.style.transform =\n              `translate3d(${current.ry * 0.85}px, ${current.rx * -0.65}px, ${layerDepth}px)`;\n          });\n\n          const unsettled = Object.keys(current).some(\n            (property) =\u003e Math.abs(target[property] - current[property]) \u003e 0.015\n          );\n\n          if (unsettled) {\n            frameId = requestAnimationFrame(renderCard);\n          } else {\n            frameId = 0;\n            if (!card.classList.contains(\"is-active\")) {\n              card.style.removeProperty(\"transform\");\n              card.style.removeProperty(\"z-index\");\n              layers.forEach((layer) =\u003e layer.style.removeProperty(\"transform\"));\n            }\n          }\n        };\n\n        const requestRender = () =\u003e {\n          if (!frameId) frameId = requestAnimationFrame(renderCard);\n        };\n\n        card.addEventListener(\"pointerenter\", (event) =\u003e {\n          if (event.pointerType === \"touch\") return;\n          restingRect = card.getBoundingClientRect();\n          card.classList.add(\"is-active\");\n          card.style.zIndex = \"12\";\n          target.y = lift;\n          target.z = depth;\n          target.scale = scale;\n          requestRender();\n        });\n\n        card.addEventListener(\"pointermove\", (event) =\u003e {\n          if (event.pointerType === \"touch\" || !restingRect) return;\n          const pointerX = clampTilt(\n            ((event.clientX - restingRect.left) / restingRect.width - 0.5) * 2,\n            -1,\n            1\n          );\n          const pointerY = clampTilt(\n            ((event.clientY - restingRect.top) / restingRect.height - 0.5) * 2,\n            -1,\n            1\n          );\n\n          // Positive Z faces the viewer, so these signs press the hovered corner away.\n          target.rx = pointerY * -maxTilt;\n          target.ry = pointerX * maxTilt;\n          target.x = pointerX * 8;\n          target.y = lift + pointerY * 6;\n          requestRender();\n        });\n\n        card.addEventListener(\"pointerleave\", (event) =\u003e {\n          if (event.pointerType === \"touch\") return;\n          card.classList.remove(\"is-active\");\n          restingRect = null;\n          Object.assign(target, { x: 0, y: 0, rx: 0, ry: 0, z: 0, scale: 1 });\n          requestRender();\n        });\n      });\n\n      if (gsapReady \u0026\u0026 !reduceMotion) {\n        document.querySelectorAll(\".project-row\").forEach((row) =\u003e {\n          const arrow = row.querySelector(\".project-arrow\");\n          row.addEventListener(\"pointerenter\", () =\u003e {\n            gsap.to(arrow, { x: 8, rotate: -8, duration: 0.35, ease: \"power3.out\" });\n          });\n          row.addEventListener(\"pointerleave\", () =\u003e {\n            gsap.to(arrow, { x: 0, rotate: 0, duration: 0.5, ease: \"elastic.out(1, 0.6)\" });\n          });\n        });\n\n        document.querySelectorAll(\".magnetic\").forEach((element) =\u003e {\n          element.addEventListener(\"pointermove\", (event) =\u003e {\n            const rect = element.getBoundingClientRect();\n            const x = event.clientX - rect.left - rect.width / 2;\n            const y = event.clientY - rect.top - rect.height / 2;\n            gsap.to(element, {\n              x: x * 0.12,\n              y: y * 0.12 - 2,\n              duration: 0.35,\n              ease: \"power3.out\"\n            });\n          });\n          element.addEventListener(\"pointerleave\", () =\u003e {\n            gsap.to(element, {\n              x: 0,\n              y: 0,\n              duration: 0.65,\n              ease: \"elastic.out(1, 0.5)\"\n            });\n          });\n        });\n      }\n    });\n  \u003c/script\u003e\n\n  \u003cscript type=\"module\"\u003e\n    import * as THREE from \"https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.module.js\";\n\n    const canvas = document.querySelector(\"#liquid-canvas\");\n    const hero = document.querySelector(\".hero\");\n    const reduceMotion = window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n\n    if (canvas \u0026\u0026 hero) {\n      try {\n        const renderer = new THREE.WebGLRenderer({\n          canvas,\n          alpha: true,\n          antialias: true,\n          powerPreference: \"high-performance\"\n        });\n\n        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.5));\n        renderer.setClearColor(0x000000, 0);\n\n        const scene = new THREE.Scene();\n        const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.1, 10);\n        camera.position.z = 1;\n        const mouse = new THREE.Vector2(0.68, 0.46);\n        const targetMouse = mouse.clone();\n        const clock = new THREE.Clock();\n\n        const material = new THREE.ShaderMaterial({\n          transparent: true,\n          depthWrite: false,\n          uniforms: {\n            uTime: { value: 0 },\n            uMouse: { value: mouse },\n            uResolution: { value: new THREE.Vector2(1, 1) }\n          },\n          vertexShader: `\n            varying vec2 vUv;\n\n            void main() {\n              vUv = uv;\n              gl_Position = vec4(position, 1.0);\n            }\n          `,\n          fragmentShader: `\n            precision highp float;\n\n            uniform float uTime;\n            uniform vec2 uMouse;\n            uniform vec2 uResolution;\n            varying vec2 vUv;\n\n            float blob(vec2 point, vec2 center, vec2 scale, float radius) {\n              vec2 delta = (point - center) * scale;\n              return smoothstep(radius, radius - 0.055, length(delta));\n            }\n\n            void main() {\n              float aspect = uResolution.x / max(uResolution.y, 1.0);\n              vec2 uv = vUv;\n              vec2 point = uv - 0.5;\n              point.x *= aspect;\n\n              vec2 cursor = uMouse - 0.5;\n              cursor.x *= aspect;\n\n              float drift = sin(uTime * 0.34) * 0.035;\n              float primary = blob(\n                point,\n                vec2(0.2 + drift, 0.06) + cursor * 0.08,\n                vec2(0.82, 1.15),\n                0.42\n              );\n\n              float secondary = blob(\n                point,\n                vec2(-0.18, -0.24 + cos(uTime * 0.26) * 0.03) + cursor * 0.035,\n                vec2(1.15, 0.92),\n                0.28\n              );\n\n              float small = blob(\n                point,\n                vec2(0.38, -0.31) - cursor * 0.04,\n                vec2(1.0, 1.0),\n                0.12\n              );\n\n              float field = max(primary, max(secondary, small));\n              float edge = smoothstep(0.03, 0.7, field) - smoothstep(0.7, 1.0, field);\n              float lens = pow(max(field, 0.0), 2.3);\n              float shimmer = 0.5 + 0.5 * sin((uv.x + uv.y) * 14.0 + uTime * 0.42);\n              vec3 ice = mix(vec3(0.96), vec3(0.42), lens);\n              vec3 color = ice + edge * vec3(0.18) + shimmer * edge * 0.06;\n              float alpha = field * 0.24 + edge * 0.13;\n\n              gl_FragColor = vec4(color, alpha);\n            }\n          `\n        });\n\n        scene.add(new THREE.Mesh(new THREE.PlaneGeometry(2, 2), material));\n\n        const resize = () =\u003e {\n          const rect = canvas.getBoundingClientRect();\n          renderer.setSize(Math.max(rect.width, 1), Math.max(rect.height, 1), false);\n          material.uniforms.uResolution.value.set(rect.width, rect.height);\n        };\n\n        const observer = new ResizeObserver(resize);\n        observer.observe(canvas);\n        resize();\n\n        hero.addEventListener(\"pointermove\", (event) =\u003e {\n          const rect = hero.getBoundingClientRect();\n          targetMouse.set(\n            (event.clientX - rect.left) / rect.width,\n            1 - (event.clientY - rect.top) / rect.height\n          );\n        }, { passive: true });\n\n        const render = () =\u003e {\n          mouse.lerp(targetMouse, reduceMotion ? 1 : 0.035);\n          material.uniforms.uTime.value = reduceMotion ? 0.8 : clock.getElapsedTime();\n          renderer.render(scene, camera);\n\n          if (!reduceMotion \u0026\u0026 !document.hidden) requestAnimationFrame(render);\n        };\n\n        document.addEventListener(\"visibilitychange\", () =\u003e {\n          if (!document.hidden \u0026\u0026 !reduceMotion) {\n            clock.getDelta();\n            requestAnimationFrame(render);\n          }\n        });\n\n        render();\n      } catch {\n        canvas.hidden = true;\n      }\n    }\n  \u003c/script\u003e\n\u003c/body\u003e\n\u003c/html\u003e\n";
const avatarImage = "";
const preloadFirst = "";
const preloadSequence = "";
const preloadFinal = "";

const securityHeaders = {
  "content-security-policy": "default-src 'self'; base-uri 'self'; form-action 'self'; frame-ancestors 'self'; img-src 'self' data: blob:; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; script-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net; connect-src 'self' https://cdn.jsdelivr.net",
  "permissions-policy": "camera=(), microphone=(), geolocation=()",
  "referrer-policy": "strict-origin-when-cross-origin",
  "x-content-type-options": "nosniff",
  "x-frame-options": "SAMEORIGIN"
};

function decodeBase64(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

const worker = {
  async fetch(request) {
    const url = new URL(request.url);
    const isHead = request.method === "HEAD";

    if (request.method !== "GET" && !isHead) {
      return new Response("Method not allowed", {
        status: 405,
        headers: { allow: "GET, HEAD", ...securityHeaders }
      });
    }

    if (url.pathname === "/assets/avatar-nguyen-manh-hung.png") {
      return new Response(isHead ? null : decodeBase64(avatarImage), {
        headers: {
          "cache-control": "public, max-age=31536000, immutable",
          "content-type": "image/png",
          ...securityHeaders
        }
      });
    }

    if (url.pathname === "/assets/preload-sequence-12fps.webp") {
      return new Response(isHead ? null : decodeBase64(preloadSequence), {
        headers: {
          "cache-control": "public, max-age=31536000, immutable",
          "content-type": "image/webp",
          ...securityHeaders
        }
      });
    }

    if (url.pathname === "/assets/preload-first.webp") {
      return new Response(isHead ? null : decodeBase64(preloadFirst), {
        headers: {
          "cache-control": "public, max-age=31536000, immutable",
          "content-type": "image/webp",
          ...securityHeaders
        }
      });
    }

    if (url.pathname === "/assets/preload-final.webp") {
      return new Response(isHead ? null : decodeBase64(preloadFinal), {
        headers: {
          "cache-control": "public, max-age=31536000, immutable",
          "content-type": "image/webp",
          ...securityHeaders
        }
      });
    }

    if (url.pathname === "/" || url.pathname === "/index.html") {
      return new Response(isHead ? null : html, {
        headers: {
          "cache-control": "public, max-age=0, must-revalidate",
          "content-type": "text/html; charset=utf-8",
          ...securityHeaders
        }
      });
    }

    return new Response("Not found", {
      status: 404,
      headers: {
        "content-type": "text/plain; charset=utf-8",
        ...securityHeaders
      }
    });
  }
};

export default worker;
